export function LandingPage({
  headline = "{{headline}}",
  cta = "{{cta}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
  supporting = {{supporting}},
}) {
  const heroStyle = {
    centered: { textAlign: "center" },
    split: { display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16, textAlign: "left" },
    minimal: { textAlign: "left" },
  }[layout] ?? {};
  return (
    <div style={{ maxWidth: 420, border: `1.5px solid ${accent}`, borderRadius: 14, padding: "28px 24px", background: "#FAF7F2", color: "#241430", fontFamily: "system-ui, sans-serif" }}>
      <div style={heroStyle}>
        <h1 style={{ margin: layout === "split" ? 0 : "0 0 16px", fontSize: 22, fontWeight: 700 }}>{headline}</h1>
        <button type="button" style={{ border: "none", background: accent, color: "#FAF7F2", fontWeight: 600, fontSize: 14, padding: "10px 18px", borderRadius: 8, cursor: "pointer" }}>{cta}</button>
      </div>
      {supporting && (
        <div style={{ marginTop: 20, paddingTop: 16, borderTop: "1px solid #24143022", fontSize: 14, color: "#241430cc" }}>
          <p style={{ margin: 0 }}>Trusted by teams who ship faster with less busywork.</p>
        </div>
      )}
    </div>
  );
}
